def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    comps = []

    # Colored components, excluding the 5-lines.
    for r in range(h):
        for c in range(w):
            if grid[r][c] in (0, 5) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if (0 <= nr < h and 0 <= nc < w and
                            grid[nr][nc] not in (0, 5) and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            comps.append(comp)

    # Find straight runs of 5s and extend the adjacent colored pattern along each run.
    for horizontal in (True, False):
        outer = h if horizontal else w
        inner = w if horizontal else h
        for fixed in range(outer):
            i = 0
            while i < inner:
                val = grid[fixed][i] if horizontal else grid[i][fixed]
                if val != 5:
                    i += 1
                    continue
                start = i
                while i < inner:
                    v = grid[fixed][i] if horizontal else grid[i][fixed]
                    if v != 5:
                        break
                    i += 1
                end = i - 1

                candidates = []
                for comp in comps:
                    rs = [p[0] for p in comp]
                    cs = [p[1] for p in comp]
                    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
                    # Component must touch a side of the run and be aligned with an endpoint.
                    if horizontal:
                        touch = ((r1 == fixed - 1 or r0 == fixed + 1) and
                                 (c0 <= start <= c1 or c0 <= end <= c1))
                        if touch:
                            candidates.append((len(comp), comp, (r0, r1, c0, c1)))
                    else:
                        touch = ((c1 == fixed - 1 or c0 == fixed + 1) and
                                 (r0 <= start <= r1 or r0 <= end <= r1))
                        if touch:
                            candidates.append((len(comp), comp, (r0, r1, c0, c1)))

                if not candidates:
                    continue
                _, comp, box = max(candidates, key=lambda x: x[0])
                r0, r1, c0, c1 = box
                pattern = {(r, c): grid[r][c] for r, c in comp}

                if horizontal:
                    # Copy the component's vertical color sequence across the run.
                    for c in range(start, end + 1):
                        for r in range(r0, r1 + 1):
                            if (r, c) in pattern:
                                color = pattern[(r, c)]
                            elif c0 == c1:
                                color = next((grid[rr][c0] for rr in range(r0, r1 + 1)
                                              if rr == r), 0)
                            else:
                                color = 0
                            if color and out[r][c] == 0:
                                out[r][c] = color
                else:
                    # Repeat the component's row-pattern along the vertical run,
                    # anchored to the component's position at the end of the run.
                    mh = r1 - r0 + 1
                    anchor = r0
                    for r in range(start, end + 1):
                        source_r = r0 + ((r - anchor) % mh)
                        for c in range(c0, c1 + 1):
                            color = pattern.get((source_r, c), 0)
                            if color and out[r][c] == 0:
                                out[r][c] = color

    return out
